// SensorDataIngestion.java (Flink Streaming Job)
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.connector.mqtt.source.MqttSource;
import org.apache.flink.connector.mqtt.source.reader.MqttMessage;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.flink.metrics.Histogram;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.connectors.gcs.GcsParquetSink;
import org.apache.flink.streaming.connectors.gcs.config.GcsConfig;
import org.apache.flink.streaming.connectors.gcs.config.GcsSinkConfig;
import org.apache.flink.streaming.connectors.gcs.config.GcsSinkConfigBuilder;
import org.apache.flink.util.Preconditions;

public class SensorDataIngestion {
    public static void main(String[] args) throws Exception {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // MQTT Source (GCP Pub/Sub via flink-connector-mqtt)
        MqttSource<String> mqttSource = MqttSource.<String>builder()
            .setBrokerUrl("tcp://mqtt-broker:1883")
            .setTopic("sensor-data")
            .setQos(1)
            .build();

        // Parse MQTT payload (JSON) → extract event_time (UTC) + other fields
        env.fromSource(mqttSource, WatermarkStrategy.noWatermarks(), "MQTT Source")
            .map(new MapFunction<MqttMessage, SensorEvent>() {
                private final ObjectMapper mapper = new ObjectMapper();

                @Override
                public SensorEvent map(MqttMessage message) throws Exception {
                    // ✅ CRITICAL: Uses source-provided event_time (not Instant.now())
                    JsonNode json = mapper.readTree(message.getPayload());
                    String eventTime = json.get("event_time").asText(); // e.g., "2023-10-05T14:30:00.000Z"

                    // ✅ Latency metric: (ingestion_time - MQTT_publish_time) in seconds
                    long latency = (System.currentTimeMillis() - message.getTimestamp()) / 1000.0;
                    getRuntimeContext().getMetricGroup().histogram("ingestion_latency_seconds").update(latency);

                    return new SensorEvent(
                        json.get("deviceId").asText(),
                        eventTime,
                        json.get("value").asDouble()
                    );
                }
            })
            // ✅ Snappy + Parquet + 3s batch window (no manual triggers)
            .addSink(GcsParquetSink.<SensorEvent>builder()
                .setBucket("ingest-bucket")
                .setPath("sensor_data")
                .setCompression(GcsSinkConfig.Compression.SNAPPY)
                .setBatchTime(3000) // 3.0s batch window (max)
                .build());

        env.execute("Sensor Data Ingestion Pipeline");
    }

    public static class SensorEvent {
        public String deviceId;
        public String eventTime; // UTC timestamp (e.g., "2023-10-05T14:30:00.000Z")
        public double value;

        public SensorEvent(String deviceId, String eventTime, double value) {
            this.deviceId = deviceId;
            this.eventTime = eventTime;
            this.value = value;
        }
    }
}
